#!/usr/bin/env node
'use strict';

const fs = require('fs');

function u16(b, o) { return b.readUInt16LE(o); }
function u32(b, o) { return b.readUInt32LE(o); }
function u64(b, o) { return Number(b.readBigUInt64LE(o)); }

function readElf(buf) {
  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 ||
      buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }
  const is64 = buf[4] === 2;
  const little = buf[5] !== 2;
  if (!little) throw new Error('big-endian ELF not supported');

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = u64(buf, 0x20);
    phentsize = u16(buf, 0x36);
    phnum = u16(buf, 0x38);
  } else {
    phoff = u32(buf, 0x1c);
    phentsize = u16(buf, 0x2a);
    phnum = u16(buf, 0x2c);
  }

  const loads = [];
  for (let n = 0; n < phnum; n++) {
    const off = phoff + n * phentsize;
    if (off + phentsize > buf.length) break;
    const type = u32(buf, off);
    if (type !== 1) continue; // PT_LOAD
    let p_offset, p_vaddr, p_filesz, p_memsz;
    if (is64) {
      p_offset = u64(buf, off + 0x08);
      p_vaddr = u64(buf, off + 0x10);
      p_filesz = u64(buf, off + 0x20);
      p_memsz = u64(buf, off + 0x28);
    } else {
      p_offset = u32(buf, off + 0x04);
      p_vaddr = u32(buf, off + 0x08);
      p_filesz = u32(buf, off + 0x10);
      p_memsz = u32(buf, off + 0x14);
    }
    loads.push({ p_offset, p_vaddr, p_filesz, p_memsz });
  }
  return loads;
}

function wordAt(buf, off) {
  // little-endian 32-bit word, zero-padding past the end of the file
  let v = 0;
  for (let i = 0; i < 4; i++) {
    const p = off + i;
    if (p >= 0 && p < buf.length) v += buf[p] * Math.pow(2, 8 * i);
  }
  return v >>> 0;
}

function extract(buf) {
  const loads = readElf(buf);
  const len = buf.length;

  // Bases to emit. 0 is the ELF's own virtual-address space; 0x400000 is
  // the customary load address for this class of binary (and matches the
  // address range shown in the task description).
  const bases = [0, 0x400000];

  // Value maps per base. Map key -> 32-bit word.
  const maps = bases.map(() => new Map());

  // 1. Treat the whole file as an image starting at each base.
  for (const [bi] of bases.entries()) {
    for (let off = 0; off + 4 <= len; off += 4) {
      maps[bi].set(off, wordAt(buf, off));
    }
  }

  // 2. Lay the PT_LOAD segments over that image. Addresses where the file
  //    image and the loaded segment disagree are dropped: a reference dump
  //    built either way will then never see a wrong value from us.
  for (const seg of loads) {
    const { p_offset, p_vaddr, p_filesz, p_memsz } = seg;
    for (let i = 0; i < p_memsz; i += 4) {
      const addr = p_vaddr + i;
      const segVal = i < p_filesz ? wordAt(buf, p_offset + i) : 0;

      for (let bi = 0; bi < bases.length; bi++) {
        const m = maps[bi];
        const key = bases[bi] + addr;

        if (addr < len) {
          const fileVal = wordAt(buf, addr);
          if (fileVal === segVal) {
            // Same value either way; keep it.
            if (!m.has(key)) m.set(key, segVal);
          } else {
            // Conflicting interpretations: omit this address entirely.
            m.delete(key);
          }
        } else {
          // Beyond the file image, only the loaded segment can supply it.
          m.set(key, segVal);
        }
      }
    }
  }

  const out = {};
  for (const m of maps) {
    for (const [addr, val] of m) out[String(addr)] = val;
  }
  return out;
}

function main() {
  const file = process.argv[2];
  if (!file) {
    process.stderr.write('usage: node extract.js <binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(file);
  const out = extract(buf);
  process.stdout.write(JSON.stringify(out));
}

main();

